import {Markdown,IssueComments,IssueRelations} from './issue-discussion.jsx';
import {AttachmentsPanel} from './attachments.jsx';
import '../../styles/issues.css';
import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Notice,Loading,Empty,Button,Field,useLoad,ConfirmButton} from '../../components/ui.jsx';
import {priorityLabel,PRIORITIES} from '../../../../shared/src/schemas/issue.js';
import {IssueEditor} from './issue-editor.jsx';
import {issueListFilters,mergeIssuePages,relativeDue} from './issue-state.js';
export async function loadIssueContext(api,projectId) {
  const {project,permissions}=await api.get('/projects/'+projectId);
  const [members,labels,issues]=await Promise.all([
    api.get('/projects/'+projectId+'/assignees?limit=200'),
    api.get('/projects/'+projectId+'/labels?limit=200'),
    api.get('/projects/'+projectId+'/issues?limit=200')
  ]);
  return {project,permissions,members:members.items,labels:labels.items,issues:issues.items};
}
function canEdit(context,user) {
  return !context.project.archived&&context.permissions.write;
}
export function IssueSummary({issue}) {
  const due=relativeDue(issue.dueDate);
  return <article className="issue-summary">
    <div><a href={'#/issues/'+issue.id}><strong>{issue.key}</strong> {issue.title}</a><p>{issue.statusName} · {priorityLabel(issue.priority)} · {issue.assignee?.name??'Unassigned'}</p></div>
    <div className="issue-tags">{issue.labels.map(label=><span key={label.id} className="label-chip" style={{borderColor:label.color}}>{label.name}</span>)}{issue.estimate!==null&&<span>{issue.estimate} points</span>}{issue.dueDate&&<span className={due.overdue?'overdue':''}>{due.label}</span>}</div>
  </article>;
}
export function Issues({params,api,navigate,user}) {
  const context=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [filters,setFilters]=useState({});
  const [creating,setCreating]=useState(false);
  const [items,setItems]=useState([]);
  const [cursor,setCursor]=useState(null);
  const [error,setError]=useState(null);
  const [busy,setBusy]=useState(false);
  const serialized=JSON.stringify(issueListFilters(filters));
  const results=useLoad(()=>api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams(JSON.parse(serialized))),[params.projectId,serialized]);
  useEffect(()=>{if(results.data){setItems(results.data.items);setCursor(results.data.nextCursor);}},[results.data]);
  function filter(field,value){setFilters(previous=>({...previous,[field]:value}));}
  async function more(){
    setBusy(true);setError(null);
    try{const page=await api.get('/projects/'+params.projectId+'/issues?'+new URLSearchParams({...issueListFilters(filters),cursor}));setItems(previous=>mergeIssuePages(previous,page.items));setCursor(page.nextCursor);}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  if(context.loading)return <Loading/>;
  if(context.error)return <Notice error={context.error}/>;
  const {project,members,labels}=context.data;
  const editable=canEdit(context.data,user);
  return <Page title={project.key+' issues'} actions={<><a href={'#/projects/'+project.id}>Project</a><a href={'#/projects/'+project.id+'/board'}>Board</a><a href={'#/projects/'+project.id+'/labels'}>Labels</a>{editable&&<Button onClick={()=>setCreating(true)}>New issue</Button>}</>}>
    <Notice error={error??results.error}/>
    {project.archived&&<Notice>This project is archived and read-only.</Notice>}
    {creating&&<IssueEditor {...context.data} onCancel={()=>setCreating(false)} onSave={async body=>{const {issue}=await api.post('/projects/'+project.id+'/issues',body);navigate('/issues/'+issue.id);}}/>}
    <div className="issue-filters" role="search" aria-label="Filter issues">
      <Field label="Search issues" name="q" type="search" value={filters.q??''} onInput={event=>filter('q',event.currentTarget.value)}/>
      <Field label="Status"><select value={filters.statusId??''} onChange={event=>filter('statusId',event.currentTarget.value)}><option value="">All statuses</option>{project.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
      <Field label="Assignee"><select value={filters.assigneeId??''} onChange={event=>filter('assigneeId',event.currentTarget.value)}><option value="">Anyone</option>{members.map(member=><option key={member.userId} value={member.userId}>{member.name}</option>)}</select></Field>
      <Field label="Label"><select value={filters.labelId??''} onChange={event=>filter('labelId',event.currentTarget.value)}><option value="">All labels</option>{labels.map(label=><option key={label.id} value={label.id}>{label.name}</option>)}</select></Field>
      <Field label="Priority"><select value={filters.priority??''} onChange={event=>filter('priority',event.currentTarget.value)}><option value="">All priorities</option>{PRIORITIES.map(priority=><option key={priority.value} value={priority.value}>{priority.label}</option>)}</select></Field>
      <Button type="button" onClick={()=>setFilters({})}>Clear filters</Button>
    </div>
    {results.loading?<Loading/>:items.length?<div className="issue-list">{items.map(issue=><IssueSummary key={issue.id} issue={issue}/>)}</div>:<Empty>No issues match these filters.</Empty>}
    {cursor&&<Button busy={busy} onClick={more}>Load more issues</Button>}
  </Page>;
}
export function IssueDetail({params,api,navigate,user}) {
  const [editing,setEditing]=useState(false);
  const [error,setError]=useState(null);
  const result=useLoad(async()=>{
    const {issue}=await api.get('/issues/'+params.issueId);
    const [context,parent]=await Promise.all([
      loadIssueContext(api,issue.projectId),
      issue.parentId?api.get('/issues/'+issue.parentId).then(result=>result.issue):null
    ]);
    return {issue,parent,...context};
  },[params.issueId]);
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const {issue,issues,parent}=result.data;
  const editable=canEdit(result.data,user);
  const children=issues.filter(item=>item.parentId===issue.id);
  const due=relativeDue(issue.dueDate);
  async function remove(){
    try{await api.delete('/issues/'+issue.id);navigate('/projects/'+issue.projectId+'/issues');}catch(error){setError(error);}
  }
  return <Page title={issue.key+' · '+issue.title} actions={<><a href={'#/projects/'+issue.projectId+'/issues'}>All issues</a>{editable&&<Button onClick={()=>setEditing(value=>!value)}>{editing?'Close editor':'Edit issue'}</Button>}</>}>
    <Notice error={error}/>
    {editing?<IssueEditor key={issue.updatedAt} {...result.data} onCancel={()=>setEditing(false)} onSave={async body=>{await api.patch('/issues/'+issue.id,body);setEditing(false);result.reload();}}/>:<>
      <section aria-label="Description"><h2>Description</h2><Markdown source={issue.description||'No description yet.'}/></section>
      <dl className="issue-properties"><dt>Status</dt><dd>{issue.statusName}</dd><dt>Priority</dt><dd>{priorityLabel(issue.priority)}</dd><dt>Assignee</dt><dd>{issue.assignee?.name??'Unassigned'}</dd><dt>Estimate</dt><dd>{issue.estimate??'Not estimated'}</dd><dt>Due</dt><dd className={due.overdue?'overdue':''}>{due.label}</dd><dt>Created by</dt><dd>{issue.creator.name}</dd><dt>Created</dt><dd><time dateTime={issue.createdAt}>{new Date(issue.createdAt).toLocaleString()}</time></dd><dt>Updated</dt><dd><time dateTime={issue.updatedAt}>{new Date(issue.updatedAt).toLocaleString()}</time></dd><dt>Parent</dt><dd>{parent?<a href={'#/issues/'+parent.id}>{parent.key} · {parent.title}</a>:'No parent issue'}</dd></dl>
      <section><h2>Labels</h2>{issue.labels.length?issue.labels.map(label=><span className="label-chip" key={label.id} style={{borderColor:label.color}}>{label.name}</span>):<Empty>No labels assigned.</Empty>}</section>
      {children.length>0&&<section><h2>Child issues</h2>{children.map(child=><IssueSummary key={child.id} issue={child}/>)}</section>}
      <IssueRelations issue={issue} issues={issues} api={api} editable={editable}/><IssueComments issue={{...issue,archived:result.data.project.archived}} api={api} user={user} members={result.data.members} canAdmin={result.data.permissions.manage}/><AttachmentsPanel api={api} issueId={issue.id}/>{editable&&<div className="danger-zone"><ConfirmButton message={'Delete '+issue.key+' permanently?'} onConfirm={remove}>Delete issue</ConfirmButton></div>}
    </>}
  </Page>;
}
export function ProjectLabels({params,api,user}) {
  const result=useLoad(()=>loadIssueContext(api,params.projectId),[params.projectId]);
  const [name,setName]=useState('');const [color,setColor]=useState('#5965d8');
  const [editing,setEditing]=useState(null);const [error,setError]=useState(null);const [busy,setBusy]=useState(false);
  async function save(event){
    event.preventDefault();setBusy(true);setError(null);
    try{if(editing)await api.patch('/labels/'+editing,{name,color});else await api.post('/projects/'+params.projectId+'/labels',{name,color});setEditing(null);setName('');result.reload();}
    catch(error){setError(error);}finally{setBusy(false);}
  }
  async function remove(label){try{await api.delete('/labels/'+label.id);result.reload();}catch(error){setError(error);}}
  if(result.loading)return <Loading/>;
  if(result.error)return <Notice error={result.error}/>;
  const editable=canEdit(result.data,user);
  return <Page title={result.data.project.key+' labels'} actions={<a href={'#/projects/'+params.projectId+'/issues'}>Issues</a>}>
    <Notice error={error}/>
    {editable&&<form onSubmit={save}><Field label="Label name" name="name" value={name} required maxLength={60} onInput={event=>setName(event.currentTarget.value)}/><Field label="Color" name="color" type="color" value={color} onInput={event=>setColor(event.currentTarget.value)}/><Button busy={busy}>{editing?'Save label':'Create label'}</Button>{editing&&<Button type="button" onClick={()=>{setEditing(null);setName('');}}>Cancel editing</Button>}</form>}
    {result.data.labels.length?<ul>{result.data.labels.map(label=><li key={label.id}><span className="label-chip" style={{borderColor:label.color}}>{label.name}</span>{editable&&<><Button onClick={()=>{setEditing(label.id);setName(label.name);setColor(label.color);}}>Edit {label.name}</Button><ConfirmButton message={'Remove '+label.name+' from this project and its issues?'} onConfirm={()=>remove(label)}>Delete {label.name}</ConfirmButton></>}</li>)}</ul>:<Empty>No labels yet.</Empty>}
  </Page>;
}
export const issueRoutes=[{path:'/projects/:projectId/issues',component:Issues},{path:'/issues/:issueId',component:IssueDetail},{path:'/projects/:projectId/labels',component:ProjectLabels}];
export const issueNavigation=[];

import { once } from 'node:events';
import { CrewClient } from '../../packages/cli/src/client.js';
async function items(client, route) {
  const result = []; let cursor = null;
  do {
    const page = await client.get(route + (route.includes('?') ? '&' : '?') + 'limit=200' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
    result.push(...page.items); cursor = page.nextCursor;
  } while (cursor);
  return result;
}
export async function seed(ctx) {
  const server = ctx.app.listen(0, '127.0.0.1');
  try {
    await once(server, 'listening', { signal: AbortSignal.timeout(3000) });
    const url = 'http://127.0.0.1:' + server.address().port;
    const people = {};
    for (const [role, name] of [['owner', 'Demo Owner'], ['member', 'Demo Member'], ['guest', 'Demo Guest']]) {
      const client = new CrewClient({ url });
      const credentials = { name, email: role + '@crew.demo', password: 'crew-demo-password-2026' };
      let user;
      try { user = (await client.post('/auth/signup', credentials)).user; }
      catch (error) { if (error.status !== 409) throw error; user = (await client.post('/auth/login', { email: credentials.email, password: credentials.password })).user; }
      people[role] = { client, user };
    }
    const client = people.owner.client;
    let org = (await items(client, '/orgs')).find(org => org.name === 'Crew Demo');
    if (!org) org = (await client.post('/orgs', { name: 'Crew Demo' })).organization;
    const members = await items(client, '/orgs/' + org.id + '/members');
    for (const role of ['member', 'guest']) {
      if (!members.some(member => member.userId === people[role].user.id)) await client.post('/orgs/' + org.id + '/members', { userId: people[role].user.id, role });
    }
    let team = (await items(client, '/orgs/' + org.id + '/teams')).find(team => team.name === 'Delivery');
    if (!team) team = (await client.post('/orgs/' + org.id + '/teams', { name: 'Delivery', description: 'Demo delivery team' })).team;
    const teamMembers = await items(client, '/teams/' + team.id + '/members');
    for (const role of ['owner', 'member']) {
      if (!teamMembers.some(member => member.userId === people[role].user.id)) await client.post('/teams/' + team.id + '/members', { userId: people[role].user.id });
    }
    let project = (await items(client, '/orgs/' + org.id + '/projects?archived=all')).find(project => project.key === 'DEMO');
    if (!project) project = (await client.post('/orgs/' + org.id + '/projects', { key: 'DEMO', name: 'Demo delivery', description: 'Explore projects, issues, boards, discussions, and sprints.' })).project;
    const guests = await items(client, '/projects/' + project.id + '/guests');
    if (!guests.some(guest => guest.userId === people.guest.user.id)) await client.post('/projects/' + project.id + '/guests', { userId: people.guest.user.id });
    const existing = await items(client, '/projects/' + project.id + '/issues');
    if (!project.archived) {
      for (const [index, title] of ['Plan the release', 'Build the team workflow', 'Welcome the crew'].entries()) {
        if (existing.some(issue => issue.title === title)) continue;
        await client.post('/projects/' + project.id + '/issues', {
          title, description: 'Demo issue. Edit this work, discuss it, and try the board.',
          statusId: project.statuses[index % project.statuses.length].id,
          assigneeId: people.member.user.id, priority: index + 1, estimate: [3, 5, 1][index]
        });
      }
    }
  } finally {
    server.closeAllConnections(); await new Promise(resolve => server.close(resolve));
  }
}

import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { writeFile, readFile } from 'node:fs/promises';
import path from 'node:path';
const attachmentBytes = Buffer.from([0, 255, 13, 10, 65, 90, 0, 128, 42]);
export async function createProject(ctx) {
  await ctx.check('project create workflow update and permission-filtered list', async () => {
    const { project } = await ctx.api('POST', '/orgs/' + ctx.ids.orgId + '/projects', {
      key: 'ACC', name: 'Acceptance project', description: 'Acceptance planning workspace'
    });
    ctx.ids.projectId = project.id; ctx.ids.projectKey = project.key;
    const statuses = project.statuses.map(({ id, name, category }) => ({ id, name: category === 'active' ? 'Building' : name, category }));
    const updated = await ctx.api('PUT', '/projects/' + project.id + '/workflow', { statuses });
    assert.deepEqual(updated.statuses.map(status => status.id), project.statuses.map(status => status.id));
    ctx.ids.browserTargetStatusId = updated.statuses.find(status => status.category === 'active').id;
    assert((await ctx.api('GET', '/projects?orgId=' + ctx.ids.orgId)).items.some(item => item.id === project.id));
    assert.equal((await ctx.request('PATCH', '/projects/' + project.id, { name: 'Denied' }, { actor: 'member' })).status, 403);
  });
}
export async function smoke(ctx) {
  const { api, check, ids } = ctx;
  const { project } = await api('GET', '/projects/' + ids.projectId);
  await check('board move within and across columns and atomic bulk fields', async () => {
    const first = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Planning first', estimate: 3 })).issue;
    const second = (await api('POST', '/projects/' + project.id + '/issues', { title: 'Planning second', estimate: 8 })).issue;
    ids.planningIssueId = first.id; ids.planningCarryIssueId = second.id;
    await api('POST', '/issues/' + second.id + '/move', { statusId: project.statuses[0].id, beforeId: first.id });
    const board = await api('GET', '/projects/' + project.id + '/board');
    const ordered = board.columns[0].issues.map(issue => issue.id);
    assert(ordered.indexOf(second.id) < ordered.indexOf(first.id));
    const edited = await api('POST', '/projects/' + project.id + '/issues/bulk', {
      issueIds: [first.id, second.id], changes: { statusId: project.statuses[1].id, assigneeId: ctx.clients.member.user.id, labelIds: [ids.issueLabelId] }
    });
    assert.equal(edited.count, 2); assert(edited.items.every(issue => issue.statusId === project.statuses[1].id && issue.labels[0].id === ids.issueLabelId));
    const denied = await ctx.request('POST', '/projects/' + project.id + '/issues/bulk', { issueIds: [first.id, second.id], changes: { statusId: project.statuses[2].id, labelIds: ['invalid-label'] } });
    assert.equal(denied.status, 422); assert.equal((await api('GET', '/issues/' + first.id)).issue.statusId, project.statuses[1].id);
  });
  await check('sprint lifecycle scope history carry-over and daily burndown persist', async () => {
    const today = new Date().toISOString().slice(0, 10);
    const nextWeek = new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10);
    const end = new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10);
    const sprint = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Acceptance sprint', goal: 'Prove delivery', startDate: today, endDate: nextWeek })).sprint;
    const carry = (await api('POST', '/projects/' + project.id + '/sprints', { name: 'Acceptance carry-over', startDate: nextWeek, endDate: end })).sprint;
    ids.sprintId = sprint.id; ids.carrySprintId = carry.id;
    await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [ids.planningIssueId, ids.planningCarryIssueId] });
    await api('DELETE', '/sprints/' + sprint.id + '/issues/' + ids.planningCarryIssueId);
    await api('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [ids.planningCarryIssueId] });
    await api('POST', '/sprints/' + sprint.id + '/start', {});
    await api('PATCH', '/issues/' + ids.planningIssueId, { statusId: project.statuses[2].id });
    const result = await api('POST', '/sprints/' + sprint.id + '/complete', { carryOverSprintId: carry.id });
    assert.deepEqual(result.result.completedIssueIds, [ids.planningIssueId]);
    assert.deepEqual(result.result.carriedIssueIds, [ids.planningCarryIssueId]);
    const burndown = await api('GET', '/sprints/' + sprint.id + '/burndown');
    assert.equal(burndown.days[0].scope, 11); assert.equal(burndown.days[0].remaining, 8);
    ids.planningBoardOrder = (await api('GET', '/projects/' + project.id + '/board')).columns.map(column => ({ statusId: column.status.id, issueIds: column.issues.filter(issue => [ids.planningIssueId, ids.planningCarryIssueId].includes(issue.id)).map(issue => issue.id) }));
  });
  await check('attachment raw upload SHA-256 metadata exact bytes and error cleanup', async () => {
    const sha256 = createHash('sha256').update(attachmentBytes).digest('hex');
    const uploaded = await ctx.request('POST', '/issues/' + ids.planningIssueId + '/attachments?name=acceptance.bin', attachmentBytes, { raw: true, headers: { 'Content-Type': 'application/octet-stream', 'X-Content-SHA256': sha256 } });
    assert.equal(uploaded.status, 201); const attachment = uploaded.data.attachment;
    ids.attachmentId = attachment.id; ids.attachmentSha256 = sha256;
    assert.equal(attachment.size, attachmentBytes.length); assert.equal(attachment.sha256, sha256);
    const downloaded = await ctx.request('GET', '/attachments/' + attachment.id + '/download', undefined, { binary: true });
    assert.equal(downloaded.status, 200); assert.deepEqual(downloaded.data, attachmentBytes);
    const invalid = await ctx.request('POST', '/issues/' + ids.planningIssueId + '/attachments?name=bad.bin', attachmentBytes, { raw: true, headers: { 'Content-Type': 'application/octet-stream', 'X-Content-SHA256': '0'.repeat(64) } });
    assert.equal(invalid.status, 422); assert.equal((await api('GET', '/issues/' + ids.planningIssueId + '/attachments')).items.length, 1);
  });
  await check('work guest public HTTP denial outside its granted project', async () => {
    await api('POST', '/projects/' + project.id + '/guests', { userId: ctx.clients.guest.user.id });
    const hidden = (await api('POST', '/orgs/' + ids.orgId + '/projects', { key: 'PRIVATE', name: 'Private planning' })).project;
    ids.privateProjectId = hidden.id;
    assert.equal((await ctx.request('GET', '/projects/' + hidden.id + '/board', undefined, { actor: 'guest' })).status, 403);
    const projects = await api('GET', '/orgs/' + ids.orgId + '/projects', undefined, 'guest');
    assert.deepEqual(projects.items.map(item => item.id), [project.id]);
    assert.equal((await ctx.request('POST', '/issues/' + ids.planningIssueId + '/move', { statusId: project.statuses[0].id }, { actor: 'guest' })).status, 403);
  });
  await check('actual project board sprint and streaming attachment CLI commands', async () => {
    assert.equal((await ctx.cli(['project', 'show', ids.projectId])).project.key, ids.projectKey);
    assert((await ctx.cli(['board', 'show', ids.projectId])).columns.length >= 3);
    assert.equal((await ctx.cli(['sprint', 'show', ids.sprintId])).sprint.status, 'completed');
    const source = path.join(ctx.dataDir, 'cli-attachment-source.bin'), output = path.join(ctx.dataDir, 'cli-attachment-output.bin');
    await writeFile(source, attachmentBytes, { mode: 0o600 });
    const attachment = (await ctx.cli(['board', 'attach', ids.planningCarryIssueId, '--file', source])).attachment;
    ids.cliAttachmentId = attachment.id;
    const downloaded = await ctx.cli(['board', 'download', attachment.id, '--output', output]);
    assert.equal(downloaded.sha256, ids.attachmentSha256); assert.deepEqual(await readFile(output), attachmentBytes);
  });
}
export async function restart(ctx) {
  const { api, ids } = ctx;
  await ctx.check('project workflow board sprint and exact attachment survive restart', async () => {
    const project = (await api('GET', '/projects/' + ids.projectId)).project;
    assert.equal(project.key, ids.projectKey); assert(project.statuses.some(status => status.id === ids.browserTargetStatusId));
    const board = await api('GET', '/projects/' + project.id + '/board');
    const order = board.columns.map(column => ({ statusId: column.status.id, issueIds: column.issues.filter(issue => [ids.planningIssueId, ids.planningCarryIssueId].includes(issue.id)).map(issue => issue.id) }));
    assert.deepEqual(order, ids.planningBoardOrder);
    const sprint = (await api('GET', '/sprints/' + ids.sprintId)).sprint;
    assert.equal(sprint.status, 'completed'); assert.deepEqual(sprint.result.carriedIssueIds, [ids.planningCarryIssueId]);
    assert.equal((await api('GET', '/sprints/' + ids.carrySprintId)).issues[0].issueId, ids.planningCarryIssueId);
    const bytes = await ctx.request('GET', '/attachments/' + ids.attachmentId + '/download', undefined, { binary: true });
    assert.deepEqual(bytes.data, attachmentBytes); assert.equal(createHash('sha256').update(bytes.data).digest('hex'), ids.attachmentSha256);
    assert((await api('GET', '/sprints/' + ids.sprintId + '/burndown')).days.length > 0);
  });
}
export async function remount(ctx) {
  await ctx.check('project and completed sprint CLI read persisted planning after fresh mount', async () => {
    assert.equal((await ctx.cli(['project', 'show', ctx.ids.projectId])).project.key, ctx.ids.projectKey);
    assert.equal((await ctx.cli(['sprint', 'show', ctx.ids.sprintId])).sprint.status, 'completed');
  });
}
export async function audit({ checks }) {
  const docs = await readFile('docs/api-work.md', 'utf8');
  for (const term of ['issue:write', 'attachment:write', 'getBurndown(ctx,id)', 'sprint_changes', 'SHA-256', 'carryOverSprintId']) assert(docs.includes(term), term);
  const sources = await Promise.all(['projects', 'boards', 'sprints', 'attachments'].map(name => readFile('packages/server/src/modules/work/' + name + '.js', 'utf8')));
  assert(sources.every(source => source.includes('requireAuth') && source.includes('permissions')));
  checks.push({ name: 'Work project/board/sprint/attachment permission entrypoints and API contracts reviewed; behavior covered by HTTP and CLI suites', ok: true });
}

import * as issues from './work-issues.mjs';
import * as planning from './work-planning.mjs';
export async function smoke(ctx) {
  await planning.createProject(ctx);
  await issues.smoke(ctx);
  await planning.smoke(ctx);
}
export async function restart(ctx) {
  await issues.restart(ctx);
  await planning.restart(ctx);
}
export async function remount(ctx) {
  await issues.remount(ctx);
  await planning.remount(ctx);
}
